// Fragen AP2 Wirtschafts- und Sozialkunde (WISO-1 bis WISO-6) – für FISI und FIAE gleich
[
  // ---------------------------------------------------------------- WISO-1 Ausbildung und Jugendarbeitsschutz
  { id: "WISO-1-01", modul: "WISO-1", typ: "mc", niveau: 1, abschnitt: "3. Probezeit, Kündigung, Ende", frage: "Wie lang muss die **Probezeit** in der Berufsausbildung nach BBiG sein?", optionen: ["Mindestens 1, höchstens 4 Monate", "Mindestens 3, höchstens 6 Monate", "Genau 6 Monate wie im Arbeitsvertrag", "Höchstens 2 Monate bei Minderjährigen", "Frei vereinbar, höchstens 1 Jahr"], richtig: 0, erklaerung: "§ 20 BBiG." },
  { id: "WISO-1-02", modul: "WISO-1", typ: "mc", niveau: 1, abschnitt: "3. Probezeit, Kündigung, Ende", frage: "Ein Azubi kündigt **in der Probezeit**. Was stimmt?", optionen: ["Beide Seiten jederzeit ohne Frist, schriftlich", "Nur mündlich und ohne Angabe von Gründen", "Beide Seiten mit 4 Wochen Frist, schriftlich", "Nur mit Zustimmung des Betriebsrats", "Nur der Betrieb, schriftlich mit Begründung"], richtig: 0, erklaerung: "§ 22 Abs. 1 BBiG, Schriftform nach Abs. 3." },
  { id: "WISO-1-03", modul: "WISO-1", typ: "mc", niveau: 2, abschnitt: "3. Probezeit, Kündigung, Ende", frage: "Nach der Probezeit will der Azubi **den Beruf wechseln**. Wie kann er kündigen?", optionen: ["Schriftlich mit einer Frist von 4 Wochen", "Nur mit Zustimmung der IHK", "Fristlos ohne Angabe von Gründen", "Mündlich mit einer Frist von 2 Wochen", "Schriftlich zum Ende des Ausbildungsjahres"], richtig: 0, erklaerung: "Bei Aufgabe oder Wechsel der Berufsausbildung: 4 Wochen Frist." },
  { id: "WISO-1-04", modul: "WISO-1", typ: "mc", niveau: 2, abschnitt: "2. Ausbildungsvertrag", frage: "Was muss **nicht** zwingend im Ausbildungsvertrag stehen?", optionen: ["Regelungen zur Gleitzeit", "Beginn und Dauer der Ausbildung", "Dauer der regelmäßigen täglichen Ausbildungszeit", "Dauer der Probezeit", "Höhe der Vergütung"], richtig: 0, erklaerung: "§ 11 BBiG zählt die Pflichtinhalte auf – Gleitzeit gehört nicht dazu." },
  { id: "WISO-1-05", modul: "WISO-1", typ: "mc", niveau: 2, abschnitt: "2. Ausbildungsvertrag", frage: "Wer trägt die Kosten für **Ausbildungsmittel** (auch für die Prüfung)?", optionen: ["Der Ausbildungsbetrieb", "Der Azubi", "Die Berufsschule", "Die IHK", "Die Agentur für Arbeit"], richtig: 0, erklaerung: "Ausbildungsmittel sind kostenlos zur Verfügung zu stellen." },
  { id: "WISO-1-06", modul: "WISO-1", typ: "mc", niveau: 1, abschnitt: "1. Duales System", frage: "Welche Stelle ist für die Berufsausbildung zum Fachinformatiker **zuständig** (Verzeichnis, Prüfungen, Überwachung)?", optionen: ["Die Industrie- und Handelskammer", "Das Arbeitsgericht", "Die Gewerkschaft", "Die Berufsgenossenschaft", "Das Finanzamt"], richtig: 0, erklaerung: "Die IHK ist zuständige Stelle nach BBiG." },
  { id: "WISO-1-07", modul: "WISO-1", typ: "zahl", niveau: 2, abschnitt: "Urlaub", frage: "Ein Azubi ist am **1. Januar 16 Jahre** alt. Wie viele **Werktage** Mindesturlaub stehen ihm in diesem Jahr zu?", richtig: 27, toleranz: 0, einheit: "Werktage", erklaerung: "Zu Beginn des Kalenderjahres noch nicht 17 → 27 Werktage." },
  { id: "WISO-1-08", modul: "WISO-1", typ: "zahl", niveau: 2, abschnitt: "Urlaub", frage: "Eine Auszubildende wird im **Juli 18**. Wie viele Werktage Mindesturlaub hat sie in diesem Kalenderjahr?", richtig: 25, toleranz: 0, einheit: "Werktage", erklaerung: "Am 1. Januar war sie 17, also noch nicht 18 → 25 Werktage." },
  { id: "WISO-1-09", modul: "WISO-1", typ: "zahl", niveau: 1, abschnitt: "Urlaub", frage: "Wie viele **Werktage** Mindesturlaub haben volljährige Arbeitnehmer nach BUrlG?", richtig: 24, toleranz: 0, einheit: "Werktage", erklaerung: "24 Werktage (Mo–Sa) = 20 Arbeitstage bei der 5-Tage-Woche." },
  { id: "WISO-1-10", modul: "WISO-1", typ: "mc", niveau: 1, abschnitt: "4. Arbeitszeit und Jugendschutz", frage: "Wie lange dürfen Jugendliche höchstens täglich arbeiten (Regelfall)?", optionen: ["8 Stunden", "10 Stunden", "6 Stunden", "9 Stunden", "12 Stunden"], richtig: 0, erklaerung: "§ 8 JArbSchG – 8,5 h nur, wenn an anderen Tagen weniger." },
  { id: "WISO-1-11", modul: "WISO-1", typ: "mc", niveau: 2, abschnitt: "4. Arbeitszeit und Jugendschutz", frage: "Wie viel **Pause** steht Jugendlichen bei mehr als **6 Stunden** Arbeit zu?", optionen: ["60 Minuten", "30 Minuten", "45 Minuten", "15 Minuten", "90 Minuten"], richtig: 0, erklaerung: "Über 4,5 h: 30 min, über 6 h: 60 min (JArbSchG § 11)." },
  { id: "WISO-1-12", modul: "WISO-1", typ: "mc", niveau: 2, abschnitt: "4. Arbeitszeit und Jugendschutz", frage: "Ein Berufsschultag hat **6 Unterrichtsstunden à 45 Minuten**. Was gilt für den Azubi?", optionen: ["Einmal pro Woche zählt der Tag als voller Arbeitstag", "Er muss danach noch mindestens 4 Stunden arbeiten", "Die Berufsschulzeit zählt nicht als Arbeitszeit", "Er muss für den Rest des Tages Urlaub nehmen", "Er darf danach höchstens 2 Stunden arbeiten"], richtig: 0, erklaerung: "Seit 2020 gilt die Anrechnung nach § 15 BBiG für alle Azubis." },
  { id: "WISO-1-13", modul: "WISO-1", typ: "mc", niveau: 2, abschnitt: "4. Arbeitszeit und Jugendschutz", frage: "Welche **Ruhezeit** müssen Jugendliche zwischen zwei Arbeitstagen haben?", optionen: ["12 Stunden", "11 Stunden", "10 Stunden", "8 Stunden", "14 Stunden"], richtig: 0, erklaerung: "Erwachsene nach ArbZG: 11 Stunden." },
  { id: "WISO-1-14", modul: "WISO-1", typ: "mc", niveau: 1, abschnitt: "4. Arbeitszeit und Jugendschutz", frage: "Was muss vor Beginn der Ausbildung eines Jugendlichen vorliegen?", optionen: ["Eine ärztliche Erstuntersuchung", "Ein polizeiliches Führungszeugnis", "Ein Sprachzertifikat", "Ein Arbeitsvertrag mit der IHK", "Eine Gewerkschaftsmitgliedschaft"], richtig: 0, erklaerung: "Nachuntersuchung nach einem Jahr." },
  { id: "WISO-1-15", modul: "WISO-1", typ: "mc", niveau: 2, abschnitt: "3. Probezeit, Kündigung, Ende", frage: "Wann endet die Ausbildung bei **bestandener** Abschlussprüfung vor Ablauf der Vertragszeit?", optionen: ["Mit Bekanntgabe des Ergebnisses durch den Ausschuss", "Mit dem Ende der vereinbarten Vertragslaufzeit", "Am Tag der letzten schriftlichen Prüfung", "Mit Zugang des Prüfungszeugnisses per Post", "Am Ende des Monats, in dem geprüft wurde"], richtig: 0, erklaerung: "§ 21 Abs. 2 BBiG." },
  { id: "WISO-1-16", modul: "WISO-1", typ: "mc", niveau: 2, abschnitt: "3. Probezeit, Kündigung, Ende", frage: "Der Azubi arbeitet nach der bestandenen Prüfung einfach weiter, ohne dass etwas vereinbart wurde. Was entsteht?", optionen: ["Ein unbefristetes Arbeitsverhältnis", "Ein befristetes Arbeitsverhältnis für 6 Monate", "Ein Praktikum", "Nichts – er arbeitet unentgeltlich", "Eine Verlängerung der Ausbildung"], richtig: 0, erklaerung: "§ 24 BBiG." },
  { id: "WISO-1-17", modul: "WISO-1", typ: "mc", niveau: 2, abschnitt: "2. Ausbildungsvertrag", frage: "Welche Vereinbarung im Ausbildungsvertrag ist **nichtig**?", optionen: ["Eine Zahlung des Azubis für die Ausbildung (Lehrgeld)", "Die Dauer der Probezeit", "Die Vergütung", "Der Urlaub", "Ausbildungsmaßnahmen außerhalb des Betriebs"], richtig: 0, erklaerung: "Entschädigungen für die Ausbildung sind nach § 12 BBiG nichtig." },
  { id: "WISO-1-18", modul: "WISO-1", typ: "mc", niveau: 1, abschnitt: "1. Duales System", frage: "Was sind die zwei Lernorte im **dualen System**?", optionen: ["Betrieb und Berufsschule", "IHK und Betrieb", "Berufsschule und Universität", "Betrieb und Arbeitsagentur", "Gewerkschaft und Betrieb"], richtig: 0, erklaerung: "Praxis im Betrieb, Theorie in der Berufsschule." },

  // ---------------------------------------------------------------- WISO-2 Arbeitsvertrag, Kündigung und Arbeitsschutz
  { id: "WISO-2-01", modul: "WISO-2", typ: "mc", niveau: 1, abschnitt: "Kündigungsschutzgesetz", frage: "Welcher Grund führt zu einer **betriebsbedingten** Kündigung?", optionen: ["Wegfall des Arbeitsplatzes durch Standortschließung", "Wiederholtes Zuspätkommen trotz Abmahnung", "Dauerhafte Krankheit mit negativer Prognose", "Grobe Beleidigung eines Vorgesetzten", "Fehlende Fahrerlaubnis bei einem Kraftfahrer"], richtig: 0, erklaerung: "Trunkenheit/Beleidigung = verhaltensbedingt, fehlende Eignung = personenbedingt, Befristung = keine Kündigung." },
  { id: "WISO-2-02", modul: "WISO-2", typ: "mc", niveau: 2, abschnitt: "Kündigungsschutzgesetz", frage: "Wann gilt das **Kündigungsschutzgesetz**?", optionen: ["Mehr als 6 Monate Betriebszugehörigkeit, mehr als 10 AN", "Ab dem ersten Tag in Betrieben mit mehr als 5 AN", "Nach 6 Monaten in jedem Betrieb unabhängig von der Größe", "Erst nach 2 Jahren in Betrieben mit mehr als 20 AN", "Nur für unbefristet Beschäftigte im öffentlichen Dienst"], richtig: 0, erklaerung: "Dann muss eine Kündigung sozial gerechtfertigt sein." },
  { id: "WISO-2-03", modul: "WISO-2", typ: "mc", niveau: 1, abschnitt: "2. Kündigung", frage: "In welcher Form muss eine Kündigung erfolgen?", optionen: ["Schriftlich mit eigenhändiger Unterschrift", "Per E-Mail mit eingescannter Unterschrift", "Mündlich vor zwei Zeugen", "In Textform per Messenger", "Formfrei, wenn der Betriebsrat zustimmt"], richtig: 0, erklaerung: "§ 623 BGB – elektronische Form ist ausgeschlossen." },
  { id: "WISO-2-04", modul: "WISO-2", typ: "mc", niveau: 2, abschnitt: "2. Kündigung", frage: "Wie lautet die **Grundkündigungsfrist** nach § 622 BGB?", optionen: ["4 Wochen zum 15. oder zum Monatsende", "2 Wochen zum 15. oder zum Monatsende", "1 Monat zum Monatsende", "6 Wochen zum Quartalsende", "3 Monate zum Monatsende"], richtig: 0, erklaerung: "Für Arbeitgeberkündigungen verlängert sie sich mit der Betriebszugehörigkeit." },
  { id: "WISO-2-05", modul: "WISO-2", typ: "mc", niveau: 2, abschnitt: "2. Kündigung", frage: "Was muss der Arbeitgeber **vor jeder Kündigung** tun, wenn es einen Betriebsrat gibt?", optionen: ["Den Betriebsrat anhören", "Die IHK informieren", "Die Gewerkschaft um Zustimmung bitten", "Das Arbeitsgericht anrufen", "Die Agentur für Arbeit benachrichtigen"], richtig: 0, erklaerung: "Ohne Anhörung ist die Kündigung unwirksam (§ 102 BetrVG)." },
  { id: "WISO-2-06", modul: "WISO-2", typ: "mc", niveau: 2, abschnitt: "Kündigungsschutzgesetz", frage: "Innerhalb welcher Frist muss eine **Kündigungsschutzklage** erhoben werden?", optionen: ["3 Wochen nach Zugang", "4 Wochen nach Zugang", "2 Monate", "1 Woche", "6 Monate"], richtig: 0, erklaerung: "Danach gilt die Kündigung als wirksam." },
  { id: "WISO-2-07", modul: "WISO-2", typ: "mc", niveau: 2, abschnitt: "Kündigungsschutzgesetz", frage: "Was geht einer **verhaltensbedingten** Kündigung in der Regel voraus?", optionen: ["Eine Abmahnung", "Eine Sozialauswahl", "Eine Betriebsversammlung", "Eine Änderungskündigung", "Ein Aufhebungsvertrag"], richtig: 0, erklaerung: "Die Abmahnung rügt, weist hin und warnt." },
  { id: "WISO-2-08", modul: "WISO-2", typ: "mc", niveau: 2, abschnitt: "Kündigungsschutzgesetz", frage: "Welche Personengruppe hat **besonderen Kündigungsschutz**?", optionen: ["Betriebsratsmitglieder", "Neue Mitarbeitende in der Probezeit", "Leiharbeitnehmer im ersten Monat", "Praktikanten", "Minijobber"], richtig: 0, erklaerung: "Ebenso Schwangere, Eltern in Elternzeit, Schwerbehinderte, JAV-Mitglieder." },
  { id: "WISO-2-09", modul: "WISO-2", typ: "mc", niveau: 2, abschnitt: "1. Arbeitsvertrag", frage: "Wie lange darf ein Arbeitsvertrag **ohne Sachgrund** höchstens befristet werden?", optionen: ["2 Jahre, höchstens dreimal verlängert", "1 Jahr, höchstens einmal verlängert", "3 Jahre, beliebig oft verlängert", "5 Jahre, höchstens zweimal verlängert", "Unbegrenzt bei schriftlichem Vertrag"], richtig: 0, erklaerung: "Teilzeit- und Befristungsgesetz; Befristung schriftlich vor Arbeitsbeginn." },
  { id: "WISO-2-10", modul: "WISO-2", typ: "mc", niveau: 1, abschnitt: "1. Arbeitsvertrag", frage: "Wie lange zahlt der Arbeitgeber bei Krankheit das **Entgelt weiter**?", optionen: ["6 Wochen", "2 Wochen", "3 Monate", "1 Jahr", "4 Wochen"], richtig: 0, erklaerung: "Danach Krankengeld der Krankenkasse." },
  { id: "WISO-2-11", modul: "WISO-2", typ: "mc", niveau: 2, abschnitt: "Kündigungsschutzgesetz", frage: "Was enthält ein **qualifiziertes Arbeitszeugnis** zusätzlich zum einfachen?", optionen: ["Beurteilung von Leistung und Verhalten", "Höhe des zuletzt gezahlten Gehalts", "Anzahl der Krankheitstage", "Gründe für die Kündigung", "Mitgliedschaft im Betriebsrat"], richtig: 0, erklaerung: "Das einfache nennt nur Art und Dauer der Tätigkeit." },
  { id: "WISO-2-12", modul: "WISO-2", typ: "mc", niveau: 1, abschnitt: "3. Arbeitsschutz", frage: "Wer ist für den **Arbeitsschutz** im Betrieb verantwortlich?", optionen: ["Der Arbeitgeber", "Der Sicherheitsbeauftragte", "Der Betriebsrat", "Die Berufsgenossenschaft", "Jeder Mitarbeitende allein"], richtig: 0, erklaerung: "Die Verantwortung bleibt beim Arbeitgeber (ArbSchG)." },
  { id: "WISO-2-13", modul: "WISO-2", typ: "mc", niveau: 2, abschnitt: "3. Arbeitsschutz", frage: "Welche Aufgabe hat ein **Sicherheitsbeauftragter**?", optionen: ["Unterstützt den Arbeitgeber, weist auf Gefahren hin", "Trägt die alleinige Verantwortung für den Arbeitsschutz", "Ist ein vom Betriebsrat gewähltes Organ", "Darf Beschäftigte bei Verstößen abmahnen", "Führt die Gefährdungsbeurteilung eigenständig durch"], richtig: 0, erklaerung: "Ehrenamtlich, ohne Weisungsbefugnis." },
  { id: "WISO-2-14", modul: "WISO-2", typ: "mc", niveau: 1, abschnitt: "3. Arbeitsschutz", frage: "Wer zahlt die Beiträge zur **gesetzlichen Unfallversicherung**?", optionen: ["Nur der Arbeitgeber", "Arbeitgeber und Arbeitnehmer je zur Hälfte", "Nur der Arbeitnehmer", "Der Staat", "Die Krankenkasse"], richtig: 0, erklaerung: "Träger sind die Berufsgenossenschaften." },
  { id: "WISO-2-15", modul: "WISO-2", typ: "mc", niveau: 1, abschnitt: "Sicherheitszeichen", frage: "Wie sieht ein **Rettungszeichen** aus (z. B. Notausgang)?", optionen: ["Grünes Rechteck mit weißem Symbol", "Roter Kreis mit Querbalken", "Blauer Kreis", "Gelbes Dreieck", "Rotes Rechteck"], richtig: 0, erklaerung: "Rot rund = Verbot, blau rund = Gebot, gelb Dreieck = Warnung, rot eckig = Brandschutz." },
  { id: "WISO-2-16", modul: "WISO-2", typ: "mc", niveau: 1, abschnitt: "Sicherheitszeichen", frage: "Ein Schild zeigt einen **Feuerlöscher** auf rotem Quadrat. Was für ein Zeichen ist das?", optionen: ["Brandschutzzeichen", "Rettungszeichen", "Gebotszeichen", "Warnzeichen", "Verbotszeichen"], richtig: 0, erklaerung: "Brandschutzeinrichtungen sind rot und eckig." },
  { id: "WISO-2-17", modul: "WISO-2", typ: "multi", niveau: 2, abschnitt: "Verhalten im Brandfall", frage: "Welche **Sofortmaßnahmen** sind im Brandfall richtig?", optionen: ["Notruf absetzen", "Gefährdete Personen evakuieren", "Alle Fenster öffnen", "Den Aufzug nutzen", "Alle Wasserhähne öffnen"], richtig: [0, 1], erklaerung: "Fenster öffnen fördert das Feuer; Aufzüge nicht benutzen." },
  { id: "WISO-2-18", modul: "WISO-2", typ: "mc", niveau: 2, abschnitt: "1. Arbeitsvertrag", frage: "Welche Schutzfrist gilt **nach** der Geburt nach dem Mutterschutzgesetz?", optionen: ["8 Wochen", "6 Wochen", "4 Wochen", "12 Monate", "3 Jahre"], richtig: 0, erklaerung: "6 Wochen vor und 8 Wochen nach der Geburt." },
  { id: "WISO-2-19", modul: "WISO-2", typ: "mc", niveau: 1, abschnitt: "1. Arbeitsvertrag", frage: "Wie lange kann **Elternzeit** je Kind höchstens genommen werden?", optionen: ["3 Jahre", "1 Jahr", "14 Monate", "6 Monate", "5 Jahre"], richtig: 0, erklaerung: "Elterngeld (vom Staat) ist davon zu unterscheiden." },

  // ---------------------------------------------------------------- WISO-3 Mitbestimmung und Tarifrecht
  { id: "WISO-3-01", modul: "WISO-3", typ: "mc", niveau: 1, abschnitt: "1. Betriebsrat", frage: "Wer ist in den **Betriebsrat wählbar** (passives Wahlrecht)?", optionen: ["Wahlberechtigte ab 18, mindestens 6 Monate im Betrieb", "Alle Beschäftigten ab 16 Jahren ohne Wartezeit", "Wahlberechtigte ab 18, mindestens 1 Jahr im Betrieb", "Wahlberechtigte ab 21, mindestens 3 Monate im Betrieb", "Alle Beschäftigten, die kein Leitungsamt haben"], richtig: 0, erklaerung: "Aktiv wählen dürfen alle ab 16." },
  { id: "WISO-3-02", modul: "WISO-3", typ: "mc", niveau: 1, abschnitt: "1. Betriebsrat", frage: "Ab wie vielen **wahlberechtigten** Arbeitnehmern kann ein Betriebsrat gewählt werden?", optionen: ["5 (davon 3 wählbar)", "10 (davon 5 wählbar)", "20 (davon 10 wählbar)", "50 (davon 25 wählbar)", "3 (alle wählbar)"], richtig: 0, erklaerung: "§ 1 BetrVG." },
  { id: "WISO-3-03", modul: "WISO-3", typ: "mc", niveau: 1, abschnitt: "1. Betriebsrat", frage: "Wie lange ist die regelmäßige **Amtszeit** des Betriebsrats?", optionen: ["4 Jahre", "2 Jahre", "3 Jahre", "5 Jahre", "1 Jahr"], richtig: 0, erklaerung: "Die JAV wird dagegen für 2 Jahre gewählt." },
  { id: "WISO-3-04", modul: "WISO-3", typ: "mc", niveau: 2, abschnitt: "1. Betriebsrat", frage: "Bei welcher Angelegenheit hat der Betriebsrat ein **echtes Mitbestimmungsrecht**?", optionen: ["Einführung technischer Einrichtungen zur Leistungskontrolle", "Festlegung der Verkaufspreise für Dienstleistungen", "Bestellung der Geschäftsführerin", "Kauf neuer Server für das Rechenzentrum", "Auswahl der Lieferanten für Hardware"], richtig: 0, erklaerung: "Soziale Angelegenheiten nach § 87 BetrVG, z. B. Zeiterfassung oder Ticketsystem." },
  { id: "WISO-3-05", modul: "WISO-3", typ: "mc", niveau: 1, abschnitt: "Betriebsvereinbarung", frage: "Zwischen wem wird eine **Betriebsvereinbarung** geschlossen?", optionen: ["Geschäftsleitung und Betriebsrat", "Gewerkschaft und Arbeitgeberverband", "IHK und Betriebsrat", "Betriebsrat und Arbeitsagentur", "Arbeitnehmer und Arbeitgeber einzeln"], richtig: 0, erklaerung: "Tarifverträge schließen Gewerkschaft und Arbeitgeber(verband)." },
  { id: "WISO-3-06", modul: "WISO-3", typ: "mc", niveau: 2, abschnitt: "2. Jugend- und Auszubildendenvertretung", frage: "Welche Aussage zur **JAV** ist richtig?", optionen: ["Sie setzt einen bestehenden Betriebsrat voraus", "Ihre regelmäßige Amtszeit beträgt 4 Jahre", "Sie schließt eigene Betriebsvereinbarungen", "Sie braucht mindestens 20 Jugendliche im Betrieb", "Sie verhandelt direkt mit der Gewerkschaft"], richtig: 0, erklaerung: "Die JAV handelt über den Betriebsrat; Amtszeit 2 Jahre." },
  { id: "WISO-3-07", modul: "WISO-3", typ: "mc", niveau: 2, abschnitt: "2. Jugend- und Auszubildendenvertretung", frage: "Welche Voraussetzung muss ein Kandidat für die **JAV** erfüllen?", optionen: ["Er darf nicht zugleich Mitglied des Betriebsrats sein", "Er muss im zweiten Ausbildungsjahr sein", "Er muss die deutsche Staatsangehörigkeit haben", "Er muss seit 6 Monaten im Betrieb sein", "Er muss Gewerkschaftsmitglied sein"], richtig: 0, erklaerung: "Wählbar sind Beschäftigte unter 25 sowie alle Auszubildenden (§ 61 Abs. 2 BetrVG) – sie dürfen nicht zugleich dem Betriebsrat angehören." },
  { id: "WISO-3-08", modul: "WISO-3", typ: "mc", niveau: 2, abschnitt: "3. Tarifrecht", frage: "Wann darf von einem Tarifvertrag abgewichen werden?", optionen: ["Wenn die Abweichung günstiger für Beschäftigte ist", "Wenn die Berufsgenossenschaft zustimmt", "Wenn der Arbeitgeber es wirtschaftlich begründet", "Wenn die Mehrheit der Belegschaft zustimmt", "Nie, Tarifverträge sind stets zwingend"], richtig: 0, erklaerung: "Günstigkeitsprinzip." },
  { id: "WISO-3-09", modul: "WISO-3", typ: "mc", niveau: 2, abschnitt: "3. Tarifrecht", frage: "Was regelt ein **Manteltarifvertrag**?", optionen: ["Allgemeine Bedingungen wie Arbeitszeit und Urlaub", "Nur die Höhe der Löhne und Gehälter", "Die Merkmale der einzelnen Entgeltgruppen", "Die Wahl und Amtszeit des Betriebsrats", "Die Höhe der Sozialversicherungsbeiträge"], richtig: 0, erklaerung: "Die Entgelthöhe steht im Lohn-/Gehaltstarifvertrag." },
  { id: "WISO-3-10", modul: "WISO-3", typ: "mc", niveau: 2, abschnitt: "3. Tarifrecht", frage: "Was bedeutet **Friedenspflicht**?", optionen: ["Keine Arbeitskämpfe über geregelte Inhalte", "Beschäftigte dürfen grundsätzlich nie streiken", "Arbeitgeber dürfen während der Laufzeit nicht kündigen", "Der Betriebsrat darf keine Streiks unterstützen", "Warnstreiks sind nur während der Laufzeit erlaubt"], richtig: 0, erklaerung: "Erst nach Ablauf/Kündigung sind Arbeitskämpfe zulässig." },
  { id: "WISO-3-11", modul: "WISO-3", typ: "mc", niveau: 2, abschnitt: "Ablauf einer Tarifrunde", frage: "Wie viel Prozent der Gewerkschaftsmitglieder müssen in der Urabstimmung **für einen Streik** stimmen?", optionen: ["75 %", "50 %", "25 %", "66 %", "100 %"], richtig: 0, erklaerung: "Für die Annahme des Verhandlungsergebnisses genügen 25 %." },
  { id: "WISO-3-12", modul: "WISO-3", typ: "mc", niveau: 3, abschnitt: "Ablauf einer Tarifrunde", frage: "Welcher Schritt folgt auf das **Scheitern der Verhandlungen** (vor einem Streik)?", optionen: ["Schlichtung, danach ggf. Urabstimmung", "Sofortiger unbefristeter Streik", "Zustimmung der Tarifparteien", "Kündigung aller Arbeitnehmer", "Allgemeinverbindlicherklärung"], richtig: 0, erklaerung: "Kündigung → Verhandlung → Schlichtung → Urabstimmung → Streik → Verhandlung → Urabstimmung → Vertrag." },
  { id: "WISO-3-13", modul: "WISO-3", typ: "mc", niveau: 2, abschnitt: "Ablauf einer Tarifrunde", frage: "Welche Aussage über **Gewerkschaften** ist zutreffend?", optionen: ["Sie können organisierten Arbeitnehmern Rechtsbeistand leisten", "Sie kontrollieren die Betriebsratswahlen", "Sie schließen Betriebsvereinbarungen", "Sie schlichten Streitigkeiten im Betrieb verbindlich", "Sie handeln Tarifverträge nur für Nichtmitglieder aus"], richtig: 0, erklaerung: "Rechtsschutz vor dem Arbeitsgericht ist eine Mitgliederleistung." },
  { id: "WISO-3-14", modul: "WISO-3", typ: "mc", niveau: 1, abschnitt: "3. Tarifrecht", frage: "Was bedeutet **Tarifautonomie**?", optionen: ["Tarifparteien verhandeln ohne staatliche Einmischung", "Der Staat legt die Löhne je Branche verbindlich fest", "Jeder Betriebsrat legt die Tarife allein fest", "Die IHK bestimmt die Tarife ihres Bezirks", "Tarife gelten nur im öffentlichen Dienst"], richtig: 0, erklaerung: "Art. 9 Abs. 3 Grundgesetz." },
  { id: "WISO-3-15", modul: "WISO-3", typ: "mc", niveau: 2, abschnitt: "1. Betriebsrat", frage: "Wobei hat der Betriebsrat nur ein **Anhörungsrecht**?", optionen: ["Bei einer Kündigung", "Bei der Regelung der Arbeitszeit", "Bei der Einführung von Überwachungstechnik", "Beim Urlaubsplan", "Bei der Betriebsordnung"], richtig: 0, erklaerung: "Anhörung ist Pflicht, eine Zustimmung ist nicht nötig; die anderen sind Mitbestimmungsrechte." },
  { id: "WISO-3-16", modul: "WISO-3", typ: "text", niveau: 2, abschnitt: "1. Betriebsrat", frage: "Welche Stelle entscheidet, wenn sich Arbeitgeber und Betriebsrat in einer mitbestimmungspflichtigen Frage nicht einigen?", richtig: ["Einigungsstelle", "die Einigungsstelle"], erklaerung: "Ihr Spruch ersetzt die Einigung." },
  { id: "WISO-3-17", modul: "WISO-3", typ: "mc", niveau: 2, abschnitt: "3. Tarifrecht", frage: "In welcher Reihenfolge stehen die Rechtsquellen des Arbeitsrechts (höchste zuerst)?", optionen: ["Gesetz – Tarifvertrag – Betriebsvereinbarung – Arbeitsvertrag", "Tarifvertrag – Gesetz – Arbeitsvertrag – Betriebsvereinbarung", "Gesetz – Betriebsvereinbarung – Tarifvertrag – Arbeitsvertrag", "Arbeitsvertrag – Betriebsvereinbarung – Tarifvertrag – Gesetz", "Betriebsvereinbarung – Gesetz – Tarifvertrag – Arbeitsvertrag"], richtig: 0, erklaerung: "Die höhere Ebene setzt Mindeststandards." },

  // ---------------------------------------------------------------- WISO-4 Sozialversicherung und Entgelt
  { id: "WISO-4-01", modul: "WISO-4", typ: "mc", niveau: 1, abschnitt: "1. Die fünf Zweige", frage: "Wer ist Träger der **Arbeitslosenversicherung**?", optionen: ["Die Bundesagentur für Arbeit", "Die Deutsche Rentenversicherung", "Die Berufsgenossenschaft", "Die Krankenkasse", "Das Finanzamt"], richtig: 0, erklaerung: "Sie zahlt Arbeitslosengeld und fördert Weiterbildung." },
  { id: "WISO-4-02", modul: "WISO-4", typ: "mc", niveau: 1, abschnitt: "1. Die fünf Zweige", frage: "Welche Versicherung leistet bei einem **Wegeunfall** zur Arbeit?", optionen: ["Gesetzliche Unfallversicherung (Berufsgenossenschaft)", "Gesetzliche Krankenversicherung (Krankenkasse)", "Gesetzliche Rentenversicherung (DRV)", "Arbeitslosenversicherung (Bundesagentur für Arbeit)", "Private Haftpflichtversicherung des Verursachers"], richtig: 0, erklaerung: "Arbeits- und Wegeunfälle sowie Berufskrankheiten." },
  { id: "WISO-4-03", modul: "WISO-4", typ: "mc", niveau: 2, abschnitt: "1. Die fünf Zweige", frage: "Welcher Beitrag wird **nur vom Arbeitnehmer** getragen?", optionen: ["Der Kinderlosenzuschlag zur Pflegeversicherung", "Der Rentenversicherungsbeitrag", "Der Unfallversicherungsbeitrag", "Der Arbeitslosenversicherungsbeitrag", "Der allgemeine Krankenversicherungsbeitrag"], richtig: 0, erklaerung: "Die Unfallversicherung trägt dagegen allein der Arbeitgeber." },
  { id: "WISO-4-04", modul: "WISO-4", typ: "mc", niveau: 2, abschnitt: "1. Die fünf Zweige", frage: "Wer ist Träger einer **medizinischen Rehabilitation**, um die Erwerbsfähigkeit zu erhalten?", optionen: ["Die Deutsche Rentenversicherung", "Die Bundesagentur für Arbeit", "Das Arbeitsgericht", "Die Gewerkschaft", "Die IHK"], richtig: 0, erklaerung: "„Reha vor Rente“." },
  { id: "WISO-4-05", modul: "WISO-4", typ: "mc", niveau: 2, abschnitt: "1. Die fünf Zweige", frage: "Was beschreibt der **Generationenvertrag**?", optionen: ["Heutige Beitragszahler finanzieren heutige Renten", "Jede Person spart ihre eigene Rente an", "Kinder zahlen die Rente ihrer Eltern direkt", "Der Staat zahlt alle Renten aus Steuern", "Arbeitgeber finanzieren die Renten allein"], richtig: 0, erklaerung: "Der demografische Wandel belastet dieses System." },
  { id: "WISO-4-06", modul: "WISO-4", typ: "mc", niveau: 2, abschnitt: "1. Die fünf Zweige", frage: "Was bedeutet die **Beitragsbemessungsgrenze**?", optionen: ["Einkommen oberhalb dieser Grenze ist beitragsfrei", "Unterhalb dieser Grenze zahlt man keine Beiträge", "Ab dieser Grenze muss man privat versichert sein", "Die Grenze für Minijobs", "Der Höchstbetrag der Rente"], richtig: 0, erklaerung: "Die Versicherungspflichtgrenze ist etwas anderes (Wechsel in die PKV)." },
  { id: "WISO-4-07", modul: "WISO-4", typ: "mc", niveau: 1, abschnitt: "1. Die fünf Zweige", frage: "Welches Prinzip gilt in der gesetzlichen Krankenversicherung?", optionen: ["Solidaritätsprinzip: Beitrag nach Einkommen", "Äquivalenzprinzip: Beitrag nach Risiko", "Kopfpauschale: gleicher Beitrag für alle", "Versicherungsprinzip: Beitrag nach Alter", "Fürsorgeprinzip: Leistung nur bei Bedürftigkeit"], richtig: 0, erklaerung: "Private Versicherungen rechnen nach Risiko." },
  { id: "WISO-4-08", modul: "WISO-4", typ: "zahl", niveau: 2, abschnitt: "2. Beiträge berechnen", frage: "Brutto **3 000 €**, kinderlos, AN-Satz insgesamt **21,75 %**. Wie hoch ist der Arbeitnehmeranteil zur Sozialversicherung (in €)?", richtig: 652.5, toleranz: 0.01, einheit: "€", erklaerung: "3 000 × 0,2175 = 652,50 €." },
  { id: "WISO-4-09", modul: "WISO-4", typ: "zahl", niveau: 2, abschnitt: "2. Beiträge berechnen", frage: "Rentenversicherung **18,6 %**, je zur Hälfte. Wie viel zahlt ein Arbeitnehmer bei **2 500 €** brutto (in €)?", richtig: 232.5, toleranz: 0.01, einheit: "€", erklaerung: "2 500 × 9,3 % = 232,50 €." },
  { id: "WISO-4-10", modul: "WISO-4", typ: "mc", niveau: 1, abschnitt: "2. Beiträge berechnen", frage: "Welche Steuerklasse haben **ledige** Arbeitnehmer ohne Kinder?", optionen: ["I", "II", "III", "V", "VI"], richtig: 0, erklaerung: "II = alleinerziehend, III/V = Ehepaare mit ungleichem Einkommen, VI = Zweitjob." },
  { id: "WISO-4-11", modul: "WISO-4", typ: "mc", niveau: 2, abschnitt: "2. Beiträge berechnen", frage: "Was wird vom Bruttogehalt **nicht** abgezogen?", optionen: ["Der Arbeitgeberanteil zur Sozialversicherung", "Die Lohnsteuer", "Die Kirchensteuer (bei Mitgliedschaft)", "Der Arbeitnehmeranteil zur Rentenversicherung", "Der Arbeitnehmeranteil zur Krankenversicherung"], richtig: 0, erklaerung: "Der AG-Anteil kommt zusätzlich zum Brutto dazu (Personalkosten)." },
  { id: "WISO-4-12", modul: "WISO-4", typ: "mc", niveau: 2, abschnitt: "1. Die fünf Zweige", frage: "Welche Versicherung ist eine **Individualversicherung** (freiwillig, privat)?", optionen: ["Berufsunfähigkeitsversicherung", "Rentenversicherung", "Pflegeversicherung", "Arbeitslosenversicherung", "Unfallversicherung der BG"], richtig: 0, erklaerung: "Beitrag nach Risiko statt nach Einkommen." },
  { id: "WISO-4-13", modul: "WISO-4", typ: "mc", niveau: 2, abschnitt: "1. Die fünf Zweige", frage: "Ab wann zahlt die Krankenkasse bei längerer Krankheit **Krankengeld**?", optionen: ["Ab der 7. Woche (nach 6 Wochen Fortzahlung)", "Ab dem ersten Tag der Krankheit", "Ab dem vierten Tag der Krankheit", "Nach drei Monaten Arbeitsunfähigkeit", "Erst nach einem Jahr Arbeitsunfähigkeit"], richtig: 0, erklaerung: "Die ersten 6 Wochen zahlt der Arbeitgeber." },
  { id: "WISO-4-14", modul: "WISO-4", typ: "mc", niveau: 3, abschnitt: "1. Die fünf Zweige", frage: "Welche Folge hat der **demografische Wandel** für die Rentenversicherung?", optionen: ["Weniger Beitragszahler, mehr Rentenbezieher", "Mehr Beitragszahler, weniger Rentenbezieher", "Die Renten steigen automatisch schneller", "Die Beitragssätze sinken dauerhaft", "Keine Auswirkung, da Umlage steuerfinanziert ist"], richtig: 0, erklaerung: "Das Umlageverfahren gerät unter Druck." },

  // ---------------------------------------------------------------- WISO-5 Unternehmen, Rechtsformen und Organisation
  { id: "WISO-5-01", modul: "WISO-5", typ: "mc", niveau: 1, abschnitt: "2. Rechtsformen", frage: "Wie hoch ist das **Mindeststammkapital einer GmbH**?", optionen: ["25 000 €", "50 000 €", "1 €", "12 500 €", "100 000 €"], richtig: 0, erklaerung: "Bei Gründung muss mindestens die Hälfte eingezahlt sein; UG ab 1 €, AG 50 000 €." },
  { id: "WISO-5-02", modul: "WISO-5", typ: "mc", niveau: 2, abschnitt: "2. Rechtsformen", frage: "Wie **haftet eine GmbH** gegenüber einem Lieferanten?", optionen: ["Mit ihrem gesamten Gesellschaftsvermögen", "Nur bis zur Höhe des Mindestkapitals", "Die Gesellschafter zusätzlich mit ihrem Privatvermögen", "Nur der Gesellschafter mit der höchsten Einlage", "Nur mit den liquiden Mitteln"], richtig: 0, erklaerung: "Die Gesellschafter haften nicht privat." },
  { id: "WISO-5-03", modul: "WISO-5", typ: "mc", niveau: 2, abschnitt: "2. Rechtsformen", frage: "Welche Aussage zur **GmbH-Gründung** ist richtig?", optionen: ["Die GmbH entsteht erst mit der Eintragung ins Handelsregister", "Der Gesellschaftsvertrag kann mündlich geschlossen werden", "Gesellschafter dürfen nicht Geschäftsführer sein", "Eine Eintragung ins Handelsregister ist freiwillig", "Der Firmenname darf identisch mit einer anderen GmbH am Ort sein"], richtig: 0, erklaerung: "Konstitutive Eintragung; Vertrag notariell; Firma unterscheidungskräftig." },
  { id: "WISO-5-04", modul: "WISO-5", typ: "mc", niveau: 1, abschnitt: "2. Rechtsformen", frage: "Wie haftet ein **Kommanditist** in einer KG?", optionen: ["Nur bis zur Höhe seiner Einlage", "Unbeschränkt mit dem Privatvermögen", "Bis zum doppelten Betrag der Einlage", "Wie ein Komplementär", "Nur mit seinem Gewinnanteil"], richtig: 0, erklaerung: "Der Komplementär haftet unbeschränkt." },
  { id: "WISO-5-05", modul: "WISO-5", typ: "mc", niveau: 1, abschnitt: "2. Rechtsformen", frage: "Welche Organe hat eine **Aktiengesellschaft**?", optionen: ["Vorstand, Aufsichtsrat, Hauptversammlung", "Geschäftsführer, Gesellschafterversammlung", "Komplementär, Kommanditist", "Inhaber, Prokurist", "Betriebsrat, JAV"], richtig: 0, erklaerung: "Der Vorstand leitet, der Aufsichtsrat kontrolliert." },
  { id: "WISO-5-06", modul: "WISO-5", typ: "zahl", niveau: 2, abschnitt: "Gewinnverteilung", frage: "Eine GmbH schüttet **90 000 €** aus. Gesellschafter A hält **30 000 €** von **120 000 €** Stammkapital. Wie viel erhält A (in €)?", richtig: 22500, toleranz: 0.01, einheit: "€", erklaerung: "30 000 / 120 000 = 25 % × 90 000 € = 22 500 €." },
  { id: "WISO-5-07", modul: "WISO-5", typ: "zahl", niveau: 3, abschnitt: "Gewinnverteilung", frage: "OHG: A 60 000 €, B 40 000 € Einlage, Gewinn 50 000 €. Vertrag: **5 %** auf die Einlage, Rest nach Köpfen. Wie viel erhält **A** (in €)?", richtig: 25500, toleranz: 0.01, einheit: "€", erklaerung: "A: 3 000 + (50 000 − 5 000) / 2 = 3 000 + 22 500 = 25 500 €." },
  { id: "WISO-5-08", modul: "WISO-5", typ: "mc", niveau: 2, abschnitt: "3. Vollmachten", frage: "Was darf ein **Prokurist** ohne besondere Befugnis **nicht**?", optionen: ["Grundstücke verkaufen oder belasten", "Einen Kredit aufnehmen", "Mitarbeitende einstellen", "Einen Prozess führen", "Waren einkaufen"], richtig: 0, erklaerung: "Außerdem keine Bilanz unterschreiben und keine Prokura erteilen." },
  { id: "WISO-5-09", modul: "WISO-5", typ: "mc", niveau: 1, abschnitt: "3. Vollmachten", frage: "Mit welchem Zusatz unterschreibt ein **Prokurist**?", optionen: ["ppa.", "i. V.", "i. A.", "gez.", "Prok."], richtig: 0, erklaerung: "i. V. = allgemeine Handlungsvollmacht, i. A. = Art- oder Einzelvollmacht." },
  { id: "WISO-5-10", modul: "WISO-5", typ: "mc", niveau: 2, abschnitt: "3. Vollmachten", frage: "Wer darf **Prokura** erteilen?", optionen: ["Nur der Inhaber bzw. gesetzliche Vertreter persönlich", "Jede Abteilungsleiterin mit Budgetverantwortung", "Ein bereits bestellter Prokurist", "Die Handlungsbevollmächtigte der Personalabteilung", "Die IHK auf Antrag des Unternehmens"], richtig: 0, erklaerung: "Ausdrücklich erteilt und ins Handelsregister eingetragen." },
  { id: "WISO-5-11", modul: "WISO-5", typ: "mc", niveau: 1, abschnitt: "1. Kaufmann, Firma, Handelsregister", frage: "Wo wird das **Handelsregister** geführt?", optionen: ["Beim Amtsgericht", "Bei der IHK", "Beim Finanzamt", "Beim Bürgeramt", "Bei der Handwerkskammer"], richtig: 0, erklaerung: "Online einsehbar; Abteilung A (Einzelkaufleute, Personengesellschaften), B (Kapitalgesellschaften)." },
  { id: "WISO-5-12", modul: "WISO-5", typ: "mc", niveau: 2, abschnitt: "4. Organisation", frage: "Welche Aussage zu **Stabsstellen** ist richtig?", optionen: ["Sie beraten die Leitung ohne Weisungsrecht", "Sie haben Weisungsrecht gegenüber allen", "Sie gibt es nur in der Matrixorganisation", "Sie ersetzen die Abteilungsleitungen", "Sie leiten das Unternehmen gemeinsam"], richtig: 0, erklaerung: "Z. B. Rechtsabteilung, Controlling, Datenschutz." },
  { id: "WISO-5-13", modul: "WISO-5", typ: "mc", niveau: 2, abschnitt: "4. Organisation", frage: "In welcher Organisationsform hat eine Stelle **mehrere Fachvorgesetzte**?", optionen: ["Mehrliniensystem", "Einliniensystem", "Stabliniensystem", "Spartenorganisation", "Holding"], richtig: 0, erklaerung: "Kurze Wege, aber Kompetenzkonflikte." },
  { id: "WISO-5-14", modul: "WISO-5", typ: "mc", niveau: 1, abschnitt: "5. Unternehmensziele", frage: "Welches Ziel ist ein **ökologisches** Unternehmensziel?", optionen: ["CO₂-Emissionen durch eine Photovoltaikanlage senken", "Gewinnbeteiligung der Mitarbeitenden", "Umsatzsteigerung um 10 %", "Einrichtung eines Betriebskindergartens", "Chancengleichheit von Frauen und Männern"], richtig: 0, erklaerung: "Gewinnbeteiligung, Kindergarten und Chancengleichheit sind soziale Ziele." },
  { id: "WISO-5-15", modul: "WISO-5", typ: "mc", niveau: 2, abschnitt: "5. Unternehmensziele", frage: "„Nur die billigsten Produkte einkaufen“ und „ein Qualitätsgütesiegel erreichen“ stehen in welcher Beziehung?", optionen: ["Konkurrierend", "Komplementär", "Indifferent", "Identisch", "Hierarchisch"], richtig: 0, erklaerung: "Das eine behindert das andere." },
  { id: "WISO-5-16", modul: "WISO-5", typ: "mc", niveau: 2, abschnitt: "5. Unternehmensziele", frage: "„Bezugskosten minimieren“ und „Gewinn maximieren“ sind …", optionen: ["komplementär", "konkurrierend", "indifferent", "unvereinbar", "rechtlich verboten"], richtig: 0, erklaerung: "Niedrigere Kosten fördern den Gewinn." },
  { id: "WISO-5-17", modul: "WISO-5", typ: "mc", niveau: 2, abschnitt: "5. Unternehmensziele", frage: "Welche Maßnahme orientiert sich **nicht** an sozialen Zielen?", optionen: ["Verpackungsabfälle aus dem Wareneingang sammeln", "Fair gehandelte Produkte verwenden", "Mitarbeitende am Gewinn beteiligen", "Einen Betriebskindergarten einrichten", "Diversity-Regeln einführen"], richtig: 0, erklaerung: "Abfall sammeln ist ein ökologisches Ziel." },
  { id: "WISO-5-18", modul: "WISO-5", typ: "mc", niveau: 1, abschnitt: "5. Unternehmensziele", frage: "Was besagt das **Minimalprinzip**?", optionen: ["Festes Ziel mit geringstem Mitteleinsatz", "Mit festen Mitteln möglichst viel erreichen", "Mit wenig Mitteln möglichst viel erreichen", "Möglichst wenige Mitarbeitende beschäftigen", "Nur die Mindestqualität liefern"], richtig: 0, erklaerung: "Das Maximalprinzip geht von festen Mitteln aus." },

  // ---------------------------------------------------------------- WISO-6 Markt, Wirtschaft und Nachhaltigkeit
  { id: "WISO-6-01", modul: "WISO-6", typ: "mc", niveau: 1, abschnitt: "Marktformen", frage: "Viele Anbieter treffen auf viele Nachfrager. Welche Marktform?", optionen: ["Polypol", "Angebotsoligopol", "Angebotsmonopol", "Nachfragemonopol", "Zweiseitiges Oligopol"], richtig: 0, erklaerung: "Vollständige Konkurrenz." },
  { id: "WISO-6-02", modul: "WISO-6", typ: "mc", niveau: 2, abschnitt: "Marktformen", frage: "Für eine Spezialsoftware gibt es **fünf Anbieter** und viele Kunden. Welche Marktform?", optionen: ["Angebotsoligopol", "Polypol", "Angebotsmonopol", "Nachfrageoligopol", "Vollkommener Markt"], richtig: 0, erklaerung: "Wenige Anbieter, viele Nachfrager." },
  { id: "WISO-6-03", modul: "WISO-6", typ: "multi", niveau: 2, abschnitt: "Vollkommener Markt", frage: "Welche Bedingungen gehören zum **vollkommenen Markt**?", optionen: ["Homogene Güter", "Vollständige Markttransparenz", "Keine persönlichen, räumlichen oder zeitlichen Präferenzen", "Nur ein Anbieter", "Staatlich festgelegte Preise"], richtig: [0, 1, 2], erklaerung: "Außerdem unendlich schnelle Reaktion und Punktmarkt." },
  { id: "WISO-6-04", modul: "WISO-6", typ: "mc", niveau: 2, abschnitt: "Vollkommener Markt", frage: "Warum ist der Markt für Steuersoftware **kein** vollkommener Markt?", optionen: ["Die Produkte sind nicht homogen", "Es gibt zu viele Anbieter am Markt", "Der Staat legt die Preise fest", "Die Käufer haben volle Markttransparenz", "Die Anbieter verlangen gleiche Preise"], richtig: 0, erklaerung: "Fehlende Homogenität und Transparenz." },
  { id: "WISO-6-05", modul: "WISO-6", typ: "mc", niveau: 2, abschnitt: "1. Markt und Preisbildung", frage: "Der Preis liegt **über** dem Gleichgewichtspreis. Was entsteht?", optionen: ["Ein Angebotsüberhang – Käufermarkt, Preise sinken", "Ein Nachfrageüberhang – Preise steigen", "Das Gleichgewicht bleibt", "Ein Monopol", "Inflation"], richtig: 0, erklaerung: "Anbieter bleiben auf Ware sitzen und senken die Preise." },
  { id: "WISO-6-06", modul: "WISO-6", typ: "mc", niveau: 2, abschnitt: "Konjunkturphasen", frage: "Das BIP sinkt über das ganze Jahr, die Arbeitslosenquote steigt von 8,5 % auf 11,5 %. Welche Phase?", optionen: ["Abschwung (Rezession)", "Aufschwung", "Boom", "Stagnation", "Inflation"], richtig: 0, erklaerung: "Negatives Wachstum und steigende Arbeitslosigkeit." },
  { id: "WISO-6-07", modul: "WISO-6", typ: "multi", niveau: 2, abschnitt: "Konjunkturphasen", frage: "Welche Ziele gehören zum **magischen Viereck**?", optionen: ["Stabiles Preisniveau", "Hoher Beschäftigungsstand", "Außenwirtschaftliches Gleichgewicht", "Stetiges und angemessenes Wachstum", "Möglichst hohe Staatsverschuldung"], richtig: [0, 1, 2, 3], erklaerung: "Magisch, weil nicht alle gleichzeitig erreichbar sind." },
  { id: "WISO-6-08", modul: "WISO-6", typ: "mc", niveau: 1, abschnitt: "Konjunkturphasen", frage: "Welcher Indikator ist ein **Spätindikator** der Konjunktur?", optionen: ["Arbeitslosenquote", "Auftragseingänge", "Geschäftsklimaindex", "Baugenehmigungen", "Aktienkurse"], richtig: 0, erklaerung: "Der Arbeitsmarkt reagiert erst verzögert." },
  { id: "WISO-6-09", modul: "WISO-6", typ: "mc", niveau: 1, abschnitt: "2. Gesamtwirtschaft", frage: "Was misst das **Bruttoinlandsprodukt**?", optionen: ["Wert aller im Inland erzeugten Güter eines Jahres", "Wert aller von Inländern weltweit erzeugten Güter", "Summe der Einkommen aller Beschäftigten", "Wert aller exportierten Güter eines Jahres", "Summe der Staatsausgaben eines Jahres"], richtig: 0, erklaerung: "Wichtigste Größe für das Wirtschaftswachstum." },
  { id: "WISO-6-10", modul: "WISO-6", typ: "mc", niveau: 1, abschnitt: "Umweltzeichen", frage: "Was bestätigt das Umweltzeichen **„Blauer Engel“**?", optionen: ["Das Produkt ist schadstoffarm und umweltschonend hergestellt", "Das Produkt ist besonders haltbar", "Das Produkt ist sicher in der Handhabung", "Das Produkt hat Umweltpreise gewonnen", "Das Produkt muss über das Duale System entsorgt werden"], richtig: 0, erklaerung: "Staatliches deutsches Umweltzeichen." },
  { id: "WISO-6-11", modul: "WISO-6", typ: "mc", niveau: 2, abschnitt: "3. Nachhaltigkeit und Umwelt", frage: "Welche Aussage zu **Emissionen** ist richtig?", optionen: ["Neben Abgasen zählen auch Geräusche (Lärm) dazu", "Emissionen entstehen nur beim Transport", "Höhere Schornsteine vermeiden Emissionen", "Emissionen sind gesetzlich nicht geregelt", "Zuständig ist der Sicherheitsbeauftragte"], richtig: 0, erklaerung: "Rechtsgrundlage ist das Bundes-Immissionsschutzgesetz." },
  { id: "WISO-6-12", modul: "WISO-6", typ: "mc", niveau: 1, abschnitt: "3. Nachhaltigkeit und Umwelt", frage: "Was steht in der **Abfallhierarchie** an erster Stelle?", optionen: ["Vermeiden", "Recycling", "Energetische Verwertung", "Beseitigen", "Wiederverwenden"], richtig: 0, erklaerung: "Vermeiden → Wiederverwenden → Recycling → Verwerten → Beseitigen." },
  { id: "WISO-6-13", modul: "WISO-6", typ: "multi", niveau: 1, abschnitt: "3. Nachhaltigkeit und Umwelt", frage: "Welche sind die **drei Säulen der Nachhaltigkeit**?", optionen: ["Ökologisch", "Ökonomisch", "Sozial", "Technisch", "Juristisch"], richtig: [0, 1, 2], erklaerung: "Umwelt, Wirtschaft und Gesellschaft." },
  { id: "WISO-6-14", modul: "WISO-6", typ: "mc", niveau: 2, abschnitt: "3. Nachhaltigkeit und Umwelt", frage: "Welche Maßnahme ist ein Beispiel für **Green IT**?", optionen: ["Serverkonsolidierung durch Virtualisierung", "Jährlich neue Smartphones für alle", "Klimaanlage im Serverraum auf 16 °C", "Alle Rechner nachts laufen lassen", "Papierausdruck jeder Mail"], richtig: 0, erklaerung: "Weniger Hardware, weniger Energie und Kühlung." },
  { id: "WISO-6-15", modul: "WISO-6", typ: "mc", niveau: 2, abschnitt: "Marktformen", frage: "Welche Behörde verbietet **Preisabsprachen** zwischen Unternehmen?", optionen: ["Das Bundeskartellamt", "Die IHK", "Das Finanzamt", "Die Bundesagentur für Arbeit", "Das Gewerbeamt"], richtig: 0, erklaerung: "Kartellverbot und Fusionskontrolle schützen den Wettbewerb." },
  { id: "WISO-6-16", modul: "WISO-6", typ: "mc", niveau: 2, abschnitt: "2. Gesamtwirtschaft", frage: "Welches Instrument nutzt die **EZB** vor allem gegen Inflation?", optionen: ["Leitzinserhöhung", "Senkung der Mehrwertsteuer", "Erhöhung des Kindergelds", "Staatliche Preisfestsetzung", "Abschaffung des Euro"], richtig: 0, erklaerung: "Höhere Zinsen dämpfen Kredite und Nachfrage." },

  // ---------------------------------------------------------------- Ergänzungen
  { id: "WISO-1-19", modul: "WISO-1", typ: "zahl", niveau: 2, abschnitt: "Urlaub", frage: "Eine Auszubildende ist am 1. Januar **17** Jahre alt. Wie viele **Werktage** Urlaub stehen ihr nach JArbSchG mindestens zu?", richtig: 25, toleranz: 0, erklaerung: "Noch nicht 18 zu Beginn des Kalenderjahres → 25 Werktage." },
  { id: "WISO-1-20", modul: "WISO-1", typ: "zahl", niveau: 1, abschnitt: "Urlaub", frage: "Eine Auszubildende ist am **01.01.** des Kalenderjahres **16 Jahre** alt. Wie viele **Werktage** Urlaub stehen ihr in diesem Jahr nach dem JArbSchG mindestens zu?", richtig: 27, erklaerung: "Maßgeblich ist das Alter zu Beginn des Kalenderjahres: „noch nicht 17“ → **27 Werktage** (unter 16: 30, unter 17: 27, unter 18: 25; § 19 JArbSchG).", toleranz: 0, einheit: "Werktage" },
  { id: "WISO-2-20", modul: "WISO-2", typ: "mc", niveau: 1, abschnitt: "1. Arbeitsvertrag", frage: "Wie hoch ist der gesetzliche **Mindestlohn** seit dem 01.01.2026 (brutto je Zeitstunde)?", optionen: ["13,90 €", "12,82 €", "14,60 €", "15,00 €"], richtig: 0, erklaerung: "2025: 12,82 € · **2026: 13,90 €** · 2027: 14,60 € (Beschluss der Mindestlohnkommission). Für Auszubildende gilt stattdessen die Mindestausbildungsvergütung nach § 17 BBiG." },
  { id: "WISO-2-21", modul: "WISO-2", typ: "mc", niveau: 1, abschnitt: "1. Arbeitsvertrag", frage: "Was gilt seit 2023 für die **Arbeitsunfähigkeitsbescheinigung** gesetzlich Versicherter?", richtig: 0, erklaerung: "Die Pflicht, die Arbeitsunfähigkeit **unverzüglich zu melden** und bei mehr als drei Kalendertagen ärztlich feststellen zu lassen, bleibt bestehen (§ 5 EFZG). Die Diagnose erfährt der Arbeitgeber nicht.", optionen: ["Der Arbeitgeber ruft die eAU bei der Krankenkasse ab", "Beschäftigte schicken den gelben Schein per Post", "Die Krankenkasse meldet dem Arbeitgeber die Diagnose", "Ein Attest ist erst ab der dritten Woche nötig"] },
  { id: "WISO-3-19", modul: "WISO-3", typ: "mc", niveau: 2, abschnitt: "2. Jugend- und Auszubildendenvertretung (JAV)", frage: "Wer darf die **JAV** wählen?", optionen: ["Beschäftigte unter 18 und alle Azubis", "Alle Beschäftigten des Betriebs", "Nur Auszubildende über 18 Jahre", "Nur die Mitglieder des Betriebsrats"], richtig: 0, erklaerung: "§ 61 Abs. 1 BetrVG; die Altersgrenze 25 für Auszubildende ist 2021 entfallen. Voraussetzung: mindestens 5 solcher Beschäftigten und ein Betriebsrat." },
  { id: "WISO-3-20", modul: "WISO-3", typ: "mc", niveau: 2, abschnitt: "3. Tarifrecht", frage: "Was ist eine **Aussperrung**?", optionen: ["Arbeitgeber schließen Beschäftigte ohne Lohn aus", "Die Gewerkschaft schließt Nichtmitglieder vom Streik aus", "Der Betriebsrat verweigert Überstunden", "Streikende werden fristlos gekündigt"], richtig: 0, erklaerung: "Die Aussperrung ist das Arbeitskampfmittel der Arbeitgeberseite. Sie muss verhältnismäßig sein; während der Aussperrung ruhen Arbeits- und Lohnpflicht." },
  { id: "WISO-4-15", modul: "WISO-4", typ: "mc", niveau: 1, abschnitt: "1. Die fünf Zweige", frage: "Wer ist Träger der gesetzlichen **Unfallversicherung**?", optionen: ["Die Berufsgenossenschaften", "Die Krankenkassen", "Die Bundesagentur für Arbeit", "Die Deutsche Rentenversicherung"], richtig: 0, erklaerung: "Die Beiträge zahlt allein der Arbeitgeber." },
  { id: "WISO-4-16", modul: "WISO-4", typ: "zahl", niveau: 1, abschnitt: "2. Beiträge berechnen", frage: "Eine Minijobberin erhält den Mindestlohn von **13,90 €** je Stunde. Wie viele **volle Stunden** darf sie 2026 im Monat höchstens arbeiten, ohne die Minijob-Grenze von **603 €** zu überschreiten?", richtig: 43, erklaerung: "603 € ÷ 13,90 €/h = 43,38 h → höchstens **43** Stunden. Die Grenze ist an den Mindestlohn gekoppelt: 13,90 € × 130 ÷ 3 = 602,33 € → 603 €.", toleranz: 0, einheit: "Stunden" },
  { id: "WISO-4-17", modul: "WISO-4", typ: "mc", niveau: 2, abschnitt: "1. Die fünf Zweige", frage: "Aus welchem Zweig der Sozialversicherung wird **Kurzarbeitergeld** gezahlt?", optionen: ["Arbeitslosenversicherung", "Krankenversicherung", "Rentenversicherung", "Unfallversicherung"], richtig: 0, erklaerung: "Kurzarbeitergeld, Arbeitslosengeld und Insolvenzgeld zahlt die **Bundesagentur für Arbeit** aus der Arbeitslosenversicherung." },
  { id: "WISO-4-18", modul: "WISO-4", typ: "zahl", niveau: 1, abschnitt: "2. Beiträge berechnen", frage: "Ab welchem **Alter** zahlen Kinderlose den Zuschlag zur Pflegeversicherung?", richtig: 23, toleranz: 0, erklaerung: "Den Zuschlag trägt der Arbeitnehmer allein." },
  { id: "WISO-4-19", modul: "WISO-4", typ: "zahl", niveau: 2, abschnitt: "2. Beiträge berechnen", frage: "Ausbildungsvergütung 1 100 €, 17 Jahre, kinderlos. Sätze: KV 14,6 % + 2,9 %, PV 3,6 %, RV 18,6 %, AV 2,6 % (je zur Hälfte). Wie hoch ist der **Arbeitnehmeranteil** in Euro?", richtig: 232.65, toleranz: 0.01, erklaerung: "(14,6 + 2,9 + 3,6 + 18,6 + 2,6) % ÷ 2 = 21,15 % → 232,65 €; kein PV-Zuschlag unter 23." },
  { id: "WISO-4-20", modul: "WISO-4", typ: "zahl", niveau: 2, abschnitt: "2. Beiträge berechnen", frage: "Bruttoentgelt **2.500,00 €**, Lohnsteuer **205,00 €**, keine Kirchensteuer, Arbeitnehmeranteil Sozialversicherung **21,15 %**. Wie hoch ist das **Nettoentgelt** in €?", richtig: 1766.25, erklaerung: "SV: 2.500,00 × 0,2115 = 528,75 € → 2.500,00 − 205,00 − 528,75 = **1.766,25 €**.", toleranz: 0.01, einheit: "€" },
  { id: "WISO-2-22", modul: "WISO-2", typ: "zahl", niveau: 1, abschnitt: "2. Kündigung", frage: "Eine Arbeitnehmerin ist seit **12 Jahren** im Betrieb. Wie viele **Monate** beträgt die gesetzliche Kündigungsfrist für eine Kündigung durch den Arbeitgeber (§ 622 BGB)?", richtig: 5, toleranz: 0, erklaerung: "Ab 12 Jahren Betriebszugehörigkeit **5 Monate zum Monatsende** (2 J.: 1, 5 J.: 2, 8 J.: 3, 10 J.: 4, 15 J.: 6, 20 J.: 7 Monate).", einheit: "Monate" },
  { id: "WISO-5-20", modul: "WISO-5", typ: "mc", niveau: 2, abschnitt: "3. Vollmachten", frage: "Welche Aussage zur **Handlungsvollmacht** trifft zu?", optionen: ["Sie wird nicht ins Handelsregister eingetragen", "Sie berechtigt zum Verkauf von Grundstücken", "Sie muss notariell beurkundet werden", "Sie kann nur einer Person erteilt werden"], richtig: 0, erklaerung: "Die Handlungsvollmacht (§ 54 HGB) ist formfrei und wird nicht eingetragen; für Grundstücke, Wechsel, Darlehen und Prozesse braucht sie eine besondere Befugnis." },
  { id: "WISO-6-17", modul: "WISO-6", typ: "mc", niveau: 1, abschnitt: "Marktformen", frage: "Wenige große Anbieter, viele Nachfrager – welche Marktform?", optionen: ["Angebotsoligopol", "Polypol", "Angebotsmonopol", "Nachfragemonopol"], richtig: 0, erklaerung: "Beispiel: Betriebssysteme, Mobilfunknetze." },
  { id: "WISO-6-18", modul: "WISO-6", typ: "mc", niveau: 2, abschnitt: "Konjunkturphasen", frage: "Vollbeschäftigung, hohe Auslastung, steigende Preise und Löhne – welche Phase?", optionen: ["Hochkonjunktur (Boom)", "Tiefstand (Depression)", "Aufschwung", "Abschwung"], richtig: 0, erklaerung: "Danach folgt der Abschwung." },
  { id: "WISO-6-19", modul: "WISO-6", typ: "multi", niveau: 2, abschnitt: "2. Gesamtwirtschaft", frage: "Welche Ziele ergänzen das magische Viereck zum **magischen Sechseck**? (mehrere richtig)", optionen: ["Gerechte Einkommens- und Vermögensverteilung", "Erhaltung einer lebenswerten Umwelt", "Stabiles Preisniveau", "Hoher Beschäftigungsstand", "Möglichst hohe Staatsquote"], richtig: [0, 1], erklaerung: "Magisches Viereck (StabG): Preisniveaustabilität, hoher Beschäftigungsstand, außenwirtschaftliches Gleichgewicht, stetiges Wachstum. Das Sechseck ergänzt **gerechte Verteilung** und **Umweltschutz**." },
  { id: "WISO-6-20", modul: "WISO-6", typ: "mc", niveau: 1, abschnitt: "Umweltzeichen", frage: "Welches Zeichen kennzeichnet in Deutschland besonders **umweltfreundliche** Produkte?", optionen: ["Blauer Engel", "CE-Zeichen", "GS-Zeichen", "TÜV-Plakette"], richtig: 0, erklaerung: "CE bestätigt nur die Einhaltung von EU-Vorschriften." },
  { id: "WISO-3-18", modul: "WISO-3", typ: "zahl", niveau: 2, abschnitt: "1. Betriebsrat", frage: "Ein Betrieb hat **65 wahlberechtigte** Arbeitnehmerinnen und Arbeitnehmer. Aus wie vielen Mitgliedern besteht der Betriebsrat?", richtig: 5, toleranz: 0, erklaerung: "§ 9 BetrVG: 5–20 → 1 · 21–50 → 3 · 51–100 → 5 · 101–200 → 7 Mitglieder." },
  { id: "WISO-5-19", modul: "WISO-5", typ: "mc", niveau: 1, abschnitt: "1. Kaufmann, Firma, Handelsregister", frage: "In welche Abteilung des **Handelsregisters** wird eine GmbH eingetragen?", optionen: ["Abteilung B", "Abteilung A", "Vereinsregister", "Gewerberegister"], richtig: 0, erklaerung: "Abteilung B: Kapitalgesellschaften (GmbH, UG, AG) · Abteilung A: Einzelkaufleute und Personengesellschaften (OHG, KG)." },
  // Ergänzungen Prüfungskatalog: Ethik, Compliance, Diversität
  { id: "WISO-6-21", modul: "WISO-6", typ: "mc", niveau: 2, abschnitt: "Ethik, Compliance und Diversität", frage: "Ab welcher Beschäftigtenzahl müssen Unternehmen nach dem **Hinweisgeberschutzgesetz** eine interne Meldestelle einrichten?", optionen: ["ab 50 Beschäftigten", "ab 10 Beschäftigten", "ab 250 Beschäftigten", "ab 500 Beschäftigten"], richtig: 0, erklaerung: "Hinweisgebende dürfen wegen einer Meldung nicht benachteiligt werden." },
  { id: "WISO-6-22", modul: "WISO-6", typ: "mc", niveau: 1, abschnitt: "Ethik, Compliance und Diversität", frage: "Was versteht man unter **Compliance**?", optionen: ["die Einhaltung von Gesetzen, Verträgen und internen Regeln", "die Steigerung des Gewinns um jeden Preis", "die freiwillige Weiterbildung der Beschäftigten", "die Werbung für nachhaltige Produkte"], richtig: 0, erklaerung: "Umgesetzt z. B. durch einen Verhaltenskodex, Schulungen und Kontrollen." },
  { id: "WISO-6-23", modul: "WISO-6", typ: "mc", niveau: 2, abschnitt: "Ethik, Compliance und Diversität", frage: "Eine Stellenanzeige sucht „junge, dynamische Entwickler“. Gegen welches Gesetz kann sie verstoßen?", optionen: ["Allgemeines Gleichbehandlungsgesetz (AGG)", "Bundesurlaubsgesetz", "Arbeitszeitgesetz", "Handelsgesetzbuch"], richtig: 0, erklaerung: "Benachteiligung wegen des Alters und (ohne m/w/d) des Geschlechts ist unzulässig." },
]
